import{_ as t,o as a,c as r,ae as i}from"./chunks/framework.EHGTsUvI.js";const h=JSON.parse('{"title":"Juicery","description":"","frontmatter":{"title":"Juicery"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/juicery.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/juicery.md"}'),o={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/juicery.md"};function n(s,e,p,l,c,d){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="juicery" tabindex="-1">Juicery <a class="header-anchor" href="#juicery" aria-label="Permalink to &quot;Juicery&quot;">​</a></h1><p>The Juicery is a production building that converts <strong>Harvested Grape Crop</strong> into <strong>Grape Juice</strong>.</p><p>Grape Juice can be sold at the liquid selling location at the middle of the map.</p><p>The Juicery is part of the <strong>Juicery License</strong> which is needed to place the Juicery on your plot and get started!</p><h2 id="factory-information" tabindex="-1">Factory Information <a class="header-anchor" href="#factory-information" aria-label="Permalink to &quot;Factory Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>180,000 Coins</td></tr><tr><td>Sell Price</td><td>36,000 Coins</td></tr><tr><td>Main Inputs</td><td>Grape Crop</td></tr><tr><td>Product</td><td>Grape Juice</td></tr><tr><td>Output</td><td>Liquid Grape Juice</td></tr><tr><td>Selling Location</td><td>Liquid Selling Point</td></tr></tbody></table><h2 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Material</th><th>Amount</th></tr></thead><tbody><tr><td>Grape Crop</td><td>5</td></tr><tr><td>Grape Juice Produced</td><td>1</td></tr></tbody></table><p>The Juicery takes Grape Crop as the only input.</p><p>There is no capacity limit to input or output of the Juicery.</p><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>The Juicery does not currently have a reliably documented fixed production time in the available community documentations.</p><p>Production is handled through the factory&#39;s internal production process rather than simple crop-style growth timer.</p><blockquote><p><strong>Note:</strong> Production time may vary depending on the current version of the game. This section should be updated if an exact in-game product time is confirmed.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>The Juicery produces <strong>Grape Juice</strong>.</p><p><strong>1 Grape Juice requires 5 Grape Crop.</strong></p><h2 id="selling-price" tabindex="-1">Selling Price <a class="header-anchor" href="#selling-price" aria-label="Permalink to &quot;Selling Price&quot;">​</a></h2><p>Grape Juice can be sold at the <strong>Liquid section of the Central Selling Point</strong>.</p><p>The current community documentation lists the maximum price at approximately <strong>15,625 Coins per unit of Grape Juice</strong>.</p><p>For example:</p><p><strong>50 × 15,625 = 781,250 Coins</strong></p><p>Therefore, 50 Grape Juice yields approximately <strong>781,250 Coins</strong>.</p><blockquote><p><strong>Note:</strong> Selling prices can change with game updates, so verify the current in-game price before treating this as a permanent value.</p></blockquote><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>To operate and transport Grape Juice efficiently, you will need:</p><ul><li><p><strong>Juicery</strong></p></li><li><p><strong>Juicery License</strong></p></li><li><p><strong>Grape Equipment</strong></p><ul><li>Moped</li><li>Grape Harvester</li><li>Grape Seeder</li></ul></li><li><p><strong>Grape Seeds</strong></p></li><li><p><strong>Vineyard</strong></p></li><li><p><strong>Crop Trailer</strong></p></li><li><p><strong>Suitable vehicle to hitch Crop Trailer</strong></p></li><li><p><strong>Suitable vehicle/trailer to transport Grape Juice</strong></p></li></ul><h2 id="how-to-use-the-juicery" tabindex="-1">How to Use the Juicery <a class="header-anchor" href="#how-to-use-the-juicery" aria-label="Permalink to &quot;How to Use the Juicery&quot;">​</a></h2><h3 id="_1-grow-grapes" tabindex="-1">1. Grow Grapes <a class="header-anchor" href="#_1-grow-grapes" aria-label="Permalink to &quot;1. Grow Grapes&quot;">​</a></h3><p>Place a vineyard of suitable size and plant it with Grape Seeds using the <strong>Moped + Grape Seeder</strong>.</p><h3 id="_2-harvest-grapes" tabindex="-1">2. Harvest Grapes <a class="header-anchor" href="#_2-harvest-grapes" aria-label="Permalink to &quot;2. Harvest Grapes&quot;">​</a></h3><p>Once the grapes are fully grown, use the <strong>Moped + Grape Harvester</strong> to collect the grapes.</p><h3 id="_3-unlock-juicery-license" tabindex="-1">3. Unlock Juicery License <a class="header-anchor" href="#_3-unlock-juicery-license" aria-label="Permalink to &quot;3. Unlock Juicery License&quot;">​</a></h3><p>Unlock the <strong>Juicery License</strong> under <strong>Farming Goal</strong>.</p><h3 id="_4-load-the-juicery" tabindex="-1">4. Load the Juicery <a class="header-anchor" href="#_4-load-the-juicery" aria-label="Permalink to &quot;4. Load the Juicery&quot;">​</a></h3><p>Use a trailer or directly deposit Grape Crop into the input of the Juicery.</p><h3 id="_5-collect-the-grape-juice" tabindex="-1">5. Collect the Grape Juice <a class="header-anchor" href="#_5-collect-the-grape-juice" aria-label="Permalink to &quot;5. Collect the Grape Juice&quot;">​</a></h3><p>Use an appropriate liquid trailer/truck to load Grape Juice from the output of the factory.</p><h3 id="_6-transport-sell-grape-juice" tabindex="-1">6. Transport &amp; Sell Grape Juice <a class="header-anchor" href="#_6-transport-sell-grape-juice" aria-label="Permalink to &quot;6. Transport &amp; Sell Grape Juice&quot;">​</a></h3><p>Once loaded into an appropriate liquid trailer/truck, transport the Grape Juice to the <strong>Liquid Sell Point</strong> in the center of the map.</p><h2 id="grape-juice-production-chain" tabindex="-1">Grape Juice Production Chain <a class="header-anchor" href="#grape-juice-production-chain" aria-label="Permalink to &quot;Grape Juice Production Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vineyard</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Grape Seeds</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Harvest Grape</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Load the Juicery</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Collect Grape Juice</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Sell</span></span></code></pre></div>`,42)])])}const g=t(o,[["render",n]]);export{h as __pageData,g as default};
